using ContentOS.Application;
using ContentOS.Contracts;
using ContentOS.Domain;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.DependencyInjection;
namespace ContentOS.Infrastructure;

public sealed partial class SocialPublishing(CoreDbContext db, IEditorialWorkbench editorial, IWatchFactory watch, IEnumerable<ISocialPublisher> publishers, ISocialEffectLedger ledger, ISocialCapabilityCatalog catalog) : ISocialPublishing
{
    private static string Json<T>(T x) => EditorialBinding.Json(x);
    private static T Read<T>(string x) => EditorialBinding.Read<T>(x);
    private static string Hash(object x) => EditorialBinding.Hash(x);
    private static string Version(CoreRecord x) => Convert.ToBase64String(x.RowVersion);
    private static void Expected(CoreRecord x, string version) { try { if (!x.RowVersion.SequenceEqual(Convert.FromBase64String(version))) throw new CoreConcurrencyException(); } catch (FormatException) { throw new RuntimeValidationException("Valid publishing rowversion required."); } }
    private async Task Access(CoreScope s, Guid u, string purpose, CancellationToken ct)
    {
        if (!await db.Universes.AnyAsync(x => x.Id == u && x.TenantId == s.TenantId, ct)) throw new CoreAccessException();
        var role = await db.Members.Where(x => x.TenantId == s.TenantId && x.Actor == s.Actor).Select(x => x.Permission).SingleOrDefaultAsync(ct);
        if (role == null || purpose == "Admin" && role != "Administrator" || purpose == "Review" && role is not ("Administrator" or "Editor") || purpose == "Write" && role is not ("Administrator" or "Editor" or "Author") || purpose == "Publish" && role is not ("Administrator" or "Editor" or "Publisher")) throw new CoreAccessException();
    }
    private async Task<T> Command<T>(CoreScope s, Guid u, Guid op, string kind, object request, string permission, Func<Task<T>> action, CancellationToken ct)
    {
        if (op == Guid.Empty) throw new RuntimeValidationException("Stable publishing operation required.");
        db.ChangeTracker.Clear(); await using var tx = await db.Database.BeginTransactionAsync(System.Data.IsolationLevel.Serializable, ct);
        await db.Database.ExecuteSqlInterpolatedAsync($"DECLARE @r int; EXEC @r=sys.sp_getapplock @Resource={"ContentOS.Social:" + s.TenantId},@LockMode='Exclusive',@LockOwner='Transaction',@LockTimeout=10000; IF @r<0 THROW 51000,'Publishing lock unavailable',1;", ct);
        await Access(s, u, permission, ct); var fingerprint = Hash(new { u, request }); var old = await db.SocialCommands.SingleOrDefaultAsync(x => x.TenantId == s.TenantId && x.OperationId == op, ct);
        if (old != null) { if (old.Actor != s.Actor || old.Kind != kind || old.Fingerprint != fingerprint) throw new RuntimeConflictException("Publishing replay differs."); return Read<T>(old.ResultJson); }
        var result = await action(); db.SocialCommands.Add(new() { Id = Guid.NewGuid(), TenantId = s.TenantId, UniverseId = u, OperationId = op, Actor = s.Actor, Kind = kind, Fingerprint = fingerprint, RequestJson = Json(request), ResultJson = Json(result) });
        db.SourceAudits.Add(new() { Id = Guid.NewGuid(), TenantId = s.TenantId, Actor = s.Actor, SubjectId = u, Action = "social." + kind });
        try { await db.SaveChangesAsync(ct); } catch (DbUpdateConcurrencyException) { throw new CoreConcurrencyException(); }
        await tx.CommitAsync(ct); return result;
    }
    private Task<SocialAccount> Account(CoreScope s, Guid u, Guid id, CancellationToken ct) => db.SocialAccounts.SingleOrDefaultAsync(x => x.Id == id && x.TenantId == s.TenantId && x.UniverseId == u, ct).ContinueWith(t => t.GetAwaiter().GetResult() ?? throw new CoreAccessException(), ct, TaskContinuationOptions.ExecuteSynchronously, TaskScheduler.Default);
    private Task<SocialPackage> Package(CoreScope s, Guid u, Guid id, CancellationToken ct) => db.SocialPackages.SingleOrDefaultAsync(x => x.Id == id && x.TenantId == s.TenantId && x.UniverseId == u, ct).ContinueWith(t => t.GetAwaiter().GetResult() ?? throw new CoreAccessException(), ct, TaskContinuationOptions.ExecuteSynchronously, TaskScheduler.Default);
    private Task<SocialPublication> Publication(CoreScope s, Guid u, Guid id, CancellationToken ct) => db.SocialPublications.SingleOrDefaultAsync(x => x.Id == id && x.TenantId == s.TenantId && x.UniverseId == u, ct).ContinueWith(t => t.GetAwaiter().GetResult() ?? throw new CoreAccessException(), ct, TaskContinuationOptions.ExecuteSynchronously, TaskScheduler.Default);
    private ISocialPublisher Publisher(string key) => publishers.SingleOrDefault(x => x.Key == key) ?? throw new EvidenceBlockedException("DeployedQualifiedPublisherRequired");
    public async Task<SocialCapability[]> CapabilitiesAsync(CoreScope s, Guid u, CancellationToken ct) { await Access(s, u, "Read", ct); return catalog.All; }
    public Task<Guid> RegisterAccountAsync(CoreScope s, Guid u, RegisterSocialAccount r, CancellationToken ct) => Command(s, u, r.OperationId, "account", r, "Admin", async () =>
    {
        CoreRules.Text(r.Key, 100, "Destination key"); CoreRules.Text(r.AccountReference, 100, "Destination account"); var c = catalog.Resolve(r.CapabilityKey);
        if (c.Platform != r.Platform || r.Mode is not ("Fixture" or "ExportOnly") || !System.Text.RegularExpressions.Regex.IsMatch(r.AccountReference, "^[A-Za-z0-9_:.-]{1,100}$") || r.AuthorizedScopes.Length > 10 || r.AuthorizedScopes.Any(x => !c.RequiredScopes.Contains(x))) throw new RuntimeValidationException("Explicit scoped destination and deployed export profile required.");
        if (r.Mode == "Fixture") { MediaRules.Attest("Fixture", r.EvidenceReference); if (!r.AccountReference.StartsWith("fixture:") || Publisher(r.Adapter).Capabilities.Qualification != "OfflineFixture") throw new EvidenceBlockedException("ExplicitFixtureDestinationRequired"); }
        else { if (r.Adapter != "manual.export.v1" || !r.EvidenceReference.StartsWith("manual:")) throw new RuntimeValidationException("Manual export binding attestation required; no token or live qualification is inferred."); }
        var old = await db.SocialAccounts.Where(x => x.TenantId == s.TenantId && x.UniverseId == u && x.Key == r.Key).OrderByDescending(x => x.Version).FirstOrDefaultAsync(ct);
        if (r.Version != (old?.Version ?? 0) + 1 || old != null && (old.Platform != r.Platform || old.AccountReference != r.AccountReference)) throw new RuntimeConflictException("Append vendor/account settings while preserving the destination; a different destination requires its own key.");
        var row = new SocialAccount { Id = Guid.NewGuid(), TenantId = s.TenantId, UniverseId = u, Key = r.Key, Version = r.Version, Platform = r.Platform, AccountReference = r.AccountReference, SnapshotJson = Json(r), Mode = r.Mode, TokenState = r.Mode == "Fixture" ? "LocalFixture" : "Unavailable" }; db.SocialAccounts.Add(row); return row.Id;
    }, ct);
    public async Task<SocialAccountView[]> AccountsAsync(CoreScope s, Guid u, CancellationToken ct) { await Access(s, u, "Read", ct); return (await db.SocialAccounts.AsNoTracking().Where(x => x.TenantId == s.TenantId && x.UniverseId == u).OrderBy(x => x.Key).ThenByDescending(x => x.Version).Take(100).ToListAsync(ct)).Select(x => { var r = Read<RegisterSocialAccount>(x.SnapshotJson); return new SocialAccountView(x.Id, r, x.Enabled, r.TokenExpiresUtc <= DateTimeOffset.UtcNow ? "Expired" : x.TokenState, r.Mode == "Fixture" ? "LocalFixtureDisconnected" : "ExportOnly", false, Version(x)); }).ToArray(); }
    public async Task ControlAccountAsync(CoreScope s, Guid u, Guid id, SocialAccountControl r, CancellationToken ct) => _ = await Command(s, u, r.OperationId, "account-control", new { id, r }, "Admin", async () => { var row = await Account(s, u, id, ct); Expected(row, r.ExpectedRowVersion); CoreRules.Text(r.EvidenceReference, 1000, "Token lifecycle evidence"); if (r.Action == "Disable") row.Enabled = false; else if (r.Action == "Revoke") { row.Enabled = false; row.TokenState = "Revoked"; } else throw new RuntimeValidationException("Disable/Revoke required; renewal appends a scoped account version."); return id; }, ct);
    private async Task Guard(CoreScope s, Guid u, SocialPackage row, string purpose, bool approved, CancellationToken ct)
    {
        if (row.ReviewStatus is "Rejected" or "Withdrawn" || approved && row.ReviewStatus != "Approved") throw new EvidenceBlockedException("CurrentDestinationPackageReviewRequired");
        var snap = Read<SocialPackageSnapshot>(row.SnapshotJson); var p = snap.Payload; var item = await editorial.InspectAsync(s, u, p.EditorialItemId, ct);
        if (item.Current == null || item.SourceOutputWithheld || item.RevisionId != p.RevisionId || item.Fingerprint != p.EditorialFingerprint || !item.Approvals.Any(x => x.Id == p.ApprovalId && x.Current)) throw new EvidenceBlockedException("PinnedEditorialApprovalExpired");
        await new SourceRightsGuard(db).CheckAsync(s, p.RevisionId, new(purpose, p.Locale, "IN", "Text"), ct);
        if (purpose == "Publish" && (Read<SocialReview>(row.ReviewJson!).Mode != "Manual" || snap.Account.Mode == "Fixture")) throw new EvidenceBlockedException("FixtureCannotAuthorizeLivePublishing");
        foreach (var image in p.Media.Where(x => x.Kind == "Image")) await MediaRightsGuard.Assert(db, s, u, image.Id, purpose == "Publish" ? "Publish" : "Reuse", true, ct);
        if (snap.Request.WatchProductionId is Guid production) { var v = await watch.ExportAsync(s, u, production, purpose, ct); if (v.Production.State != "Approved" || v.Production.Snapshot.Script.RevisionId != p.RevisionId || !p.Media.Where(x => x.Kind == "Video").All(x => v.Production.Artifacts.Any(a => a.Id == x.Id && a.Sha256 == x.Sha256))) throw new EvidenceBlockedException("CurrentMatchingReviewedWATCHMasterRequired"); }
        SocialRules.Payload(p, snap.Capability);
    }
    private async Task<SocialPackageView> View(CoreScope s, Guid u, SocialPackage row, CancellationToken ct)
    { var blocks = new List<string>(); try { await Guard(s, u, row, "Export", false, ct); } catch (Exception e) when (e is EvidenceBlockedException or RightsBlockedException) { blocks.Add(e.Message); } return new(row.Id, row.Key, row.ReviewStatus, row.PayloadHash, blocks.Count > 0 ? null : Read<SocialPackageSnapshot>(row.SnapshotJson), Version(row), blocks.ToArray()); }
    public async Task<SocialPackageView> PrepareAsync(CoreScope s, Guid u, CreateSocialPackage r, CancellationToken ct)
    {
        var id = await Command(s, u, r.OperationId, "prepare", r, "Write", async () =>
        {
            CoreRules.Text(r.Key, 100, "Package key"); var account = await Account(s, u, r.AccountId, ct); var binding = Read<RegisterSocialAccount>(account.SnapshotJson); var c = catalog.Resolve(binding.CapabilityKey); var packet = await editorial.InspectAsync(s, u, r.EditorialItemId, ct);
            if (packet.Current == null || packet.SourceOutputWithheld || !packet.Approvals.Any(x => x.Current) || packet.State is not ("Approved" or "Scheduled" or "Published")) throw new EvidenceBlockedException("ApprovedContentRequiredBeforeChannelPackaging");
            if (r.ImageVersionIds.Length > c.MaxImages || r.ImageVersionIds.Distinct().Count() != r.ImageVersionIds.Length) throw new RuntimeValidationException("Distinct bounded media required.");
            var assets = new List<SocialMedia>(); foreach (var image in r.ImageVersionIds) { var version = await MediaRightsGuard.Assert(db, s, u, image, "Reuse", true, ct); var material = Read<MediaLibrary.Material>(version.SnapshotJson); if (material.Info.Mime != "image/png") throw new RuntimeValidationException("Approved PNG image/thumbnail required."); assets.Add(new(image, "Image", material.Info.Sha256, material.Info.Length, material.Info.Mime, "", Role: r.Format is "Short" or "Video" ? "Thumbnail" : r.Format == "Carousel" ? "Slide" : "Image")); }
            if (r.WatchProductionId is Guid production) { var v = await watch.ExportAsync(s, u, production, "Export", ct); if (v.Production.State != "Approved" || v.Production.Snapshot.Script.RevisionId != packet.RevisionId) throw new EvidenceBlockedException("ApprovedWATCHOfExactContentRequired"); var a = v.Production.Artifacts.SingleOrDefault(x => x.Aspect == r.Aspect) ?? throw new EvidenceBlockedException("RequestedMasterAspectRequired"); assets.Add(new(a.Id, "Video", a.Sha256, a.Length, "video/mp4", a.Aspect, production, a.DurationSeconds, "Master")); }
            var text = r.Caption.Length == 0 ? packet.Current.Body : r.Caption; if (r.Link.Length > 0) text += "\n" + r.Link;
            var slides = r.Format == "Carousel" ? SocialRules.Slides(packet.Current.Body, r.ImageVersionIds.Length) : [];
            var head = await db.Contents.AsNoTracking().SingleAsync(x => x.Id == packet.ContentId, ct); var payload = new SocialPayload(packet.Id, packet.RevisionId, packet.Approvals.Single(x => x.Current).Id, packet.Fingerprint, binding.Platform, binding.AccountReference, r.Format, r.DestinationTitle.Length == 0 ? packet.Current.Title : r.DestinationTitle, text, r.Format == "Article" ? packet.Current.Body : "", r.CampaignId, r.Link, slides, assets.ToArray(), r.MadeForKids, head.LocaleId, head.AudienceId, packet.Current.Kind, packet.Citations, packet.Claims.Select(x => x.Label).ToArray()); SocialRules.Payload(payload, c);
            var row = new SocialPackage { Id = Guid.NewGuid(), TenantId = s.TenantId, UniverseId = u, Key = r.Key, AccountId = account.Id, EditorialItemId = packet.Id, RevisionId = packet.RevisionId, SnapshotJson = Json(new SocialPackageSnapshot(r, binding, c, payload, binding.Mode == "Fixture" ? Publisher(binding.Adapter).Capabilities : null)), PayloadHash = Hash(new { Account = binding, Capability = c, Payload = payload, Provider = binding.Mode == "Fixture" ? Publisher(binding.Adapter).Capabilities : null }) };
            await Guard(s, u, row, "Export", false, ct); db.SocialPackages.Add(row); var draft = new SocialPublication { Id = Guid.NewGuid(), TenantId = s.TenantId, UniverseId = u, PackageId = row.Id, AccountId = account.Id, Actor = s.Actor, SnapshotJson = row.SnapshotJson, State = "Draft" }; db.SocialPublications.Add(draft); History(draft, "Draft", "Immutable destination package awaiting review and scheduling."); return row.Id;
        }, ct); return await View(s, u, await Package(s, u, id, ct), ct);
    }
    public async Task<SocialPackageView[]> PackagesAsync(CoreScope s, Guid u, CancellationToken ct) { await Access(s, u, "Read", ct); var result = new List<SocialPackageView>(); foreach (var r in await db.SocialPackages.AsNoTracking().Where(x => x.TenantId == s.TenantId && x.UniverseId == u).OrderByDescending(x => x.CreatedUtc).Take(100).ToListAsync(ct)) result.Add(await View(s, u, r, ct)); return result.ToArray(); }
    public async Task ReviewAsync(CoreScope s, Guid u, Guid id, SocialReview r, CancellationToken ct) => _ = await Command(s, u, r.OperationId, "review", new { id, r }, "Review", async () =>
    {
        var row = await Package(s, u, id, ct); Expected(row, r.ExpectedRowVersion); MediaRules.Attest(r.Mode, r.EvidenceReference);
        if (r.PayloadHash != row.PayloadHash || r.Decision is not ("Approve" or "Reject" or "Withdraw") || r.Decision == "Approve" && row.ReviewStatus != "Draft") throw new EvidenceBlockedException("ExactFreshPayloadReviewRequired");
        if (r.Decision == "Approve") await Guard(s, u, row, "Export", false, ct); row.ReviewStatus = r.Decision == "Approve" ? "Approved" : r.Decision == "Reject" ? "Rejected" : "Withdrawn"; row.ReviewJson = Json(r); return id;
    }, ct);
    public async Task<SocialExport> ExportAsync(CoreScope s, Guid u, Guid id, CancellationToken ct)
    { await Access(s, u, "Read", ct); var row = await Package(s, u, id, ct); await Guard(s, u, row, "Export", true, ct); var v = await View(s, u, row, ct); var pub = await db.SocialPublications.AsNoTracking().SingleOrDefaultAsync(x => x.PackageId == id, ct); return new(v, pub == null ? null : await PublicationView(pub, ct), "ExportOnly;NotPublished", ["Private reviewed manifest; media IDs refer to owned authenticated previews.", "Obtain genuine publication rights/human reviews and verify this platform/account's current permissions before manual upload.", "Record actual external ID/URL with manual evidence; a receipt is not adapter qualification."]); }
    public async Task<SocialPublicationView> ScheduleAsync(CoreScope s, Guid u, ScheduleSocial r, CancellationToken ct)
    {

        var id = await Command(s, u, r.OperationId, "schedule", r, "Publish", async () => { var instant = SocialRules.Schedule(r); var package = await Package(s, u, r.PackageId, ct); await Guard(s, u, package, "Export", true, ct); var account = await Account(s, u, package.AccountId, ct); var binding = Read<RegisterSocialAccount>(account.SnapshotJson); if (!account.Enabled || account.TokenState == "Revoked" || binding.TokenExpiresUtc <= DateTimeOffset.UtcNow) throw new EvidenceBlockedException("AccountDisabledExpiredOrRevoked"); if (binding.Mode == "Fixture" && binding.AuthorizedScopes.Except(catalog.Resolve(binding.CapabilityKey).RequiredScopes).Any()) throw new EvidenceBlockedException("DestinationScopesMismatch"); if (binding.Mode == "Fixture" && catalog.Resolve(binding.CapabilityKey).RequiredScopes.Except(binding.AuthorizedScopes).Any()) throw new EvidenceBlockedException("DestinationScopesRequired"); var existing = await db.SocialPublications.SingleOrDefaultAsync(x => x.PackageId == package.Id, ct); if (existing != null && existing.State == "Draft") { existing.Actor = s.Actor; existing.State = "Scheduled"; existing.ScheduledUtc = instant; existing.NextUtc = instant; existing.Timezone = r.Timezone; existing.DeadlineUtc = instant.AddSeconds(r.DeadlineSeconds); existing.MaxAttempts = r.MaxAttempts; History(existing, "Scheduled", binding.Mode == "Fixture" ? "Fixture only; no platform call" : "ExportOnly; manual action required"); return existing.Id; } if (existing != null) { if (existing.ScheduledUtc != instant || existing.Timezone != r.Timezone || existing.MaxAttempts != r.MaxAttempts || existing.DeadlineUtc != instant.AddSeconds(r.DeadlineSeconds)) throw new RuntimeConflictException("One intended publication per immutable package."); return existing.Id; } var row = new SocialPublication { Id = Guid.NewGuid(), TenantId = s.TenantId, UniverseId = u, PackageId = package.Id, AccountId = account.Id, Actor = s.Actor, SnapshotJson = package.SnapshotJson, State = "Scheduled", ScheduledUtc = instant, NextUtc = instant, Timezone = r.Timezone, DeadlineUtc = instant.AddSeconds(r.DeadlineSeconds), MaxAttempts = r.MaxAttempts }; db.SocialPublications.Add(row); History(row, "Scheduled", binding.Mode == "Fixture" ? "Fixture only; no platform call" : "ExportOnly; manual action required"); return row.Id; }, ct); return await PublicationView(await Publication(s, u, id, ct), ct);
    }
    private void History(SocialPublication row, string kind, string detail) { db.SocialHistory.Add(new() { Id = Guid.NewGuid(), TenantId = row.TenantId, UniverseId = row.UniverseId, PublicationId = row.Id, Kind = kind, Detail = detail }); db.SocialNotifications.Add(new() { Id = Guid.NewGuid(), TenantId = row.TenantId, UniverseId = row.UniverseId, PublicationId = row.Id, Kind = kind, Detail = detail }); }
    private async Task<SocialDispatch> Dispatch(SocialPublication row, CancellationToken ct) { var snap = Read<SocialPackageSnapshot>(row.SnapshotJson); return new(row.Id, row.TenantId, row.UniverseId, snap.Account.Platform, snap.Account.AccountReference, snap.Account.Adapter, await db.SocialPackages.Where(x => x.Id == row.PackageId && x.TenantId == row.TenantId && x.UniverseId == row.UniverseId).Select(x => x.PayloadHash).SingleAsync(ct), snap.Payload); }
    private async Task<SocialPublicationView> PublicationView(SocialPublication row, CancellationToken ct) { var snap = Read<SocialPackageSnapshot>(row.SnapshotJson); var history = await db.SocialHistory.AsNoTracking().Where(x => x.PublicationId == row.Id).OrderBy(x => x.CreatedUtc).Select(x => new SocialHistoryView(x.Kind, x.Detail, x.CreatedUtc)).ToArrayAsync(ct); return new(row.Id, row.PackageId, row.State, snap.Account.Platform, snap.Account.AccountReference, snap.Account.Adapter, row.ScheduledUtc, row.Timezone, row.Attempts, row.RemoteId, row.RemoteUrl, row.Outcome, Version(row), history, snap.Account.Mode); }
    public async Task<SocialPublicationView[]> PublicationsAsync(CoreScope s, Guid u, CancellationToken ct) { await Access(s, u, "Read", ct); var result = new List<SocialPublicationView>(); foreach (var row in await db.SocialPublications.AsNoTracking().Where(x => x.TenantId == s.TenantId && x.UniverseId == u).OrderByDescending(x => x.CreatedUtc).Take(100).ToArrayAsync(ct)) result.Add(await PublicationView(row, ct)); return result.ToArray(); }
    public async Task<SocialNotificationView[]> NotificationsAsync(CoreScope s, Guid u, CancellationToken ct) { await Access(s, u, "Read", ct); return await db.SocialNotifications.AsNoTracking().Where(x => x.TenantId == s.TenantId && x.UniverseId == u).OrderByDescending(x => x.CreatedUtc).Take(100).Select(x => new SocialNotificationView(x.Id, x.PublicationId, x.Kind, x.Detail, x.Acknowledged, Convert.ToBase64String(x.RowVersion))).ToArrayAsync(ct); }
    public async Task AcknowledgeAsync(CoreScope s, Guid u, Guid id, SocialControl r, CancellationToken ct) => _ = await Command(s, u, r.OperationId, "notification-ack", new { id, r }, "Read", async () => { var row = await db.SocialNotifications.SingleOrDefaultAsync(x => x.Id == id && x.TenantId == s.TenantId && x.UniverseId == u, ct) ?? throw new CoreAccessException(); Expected(row, r.ExpectedRowVersion); if (r.Action != "Acknowledge") throw new RuntimeValidationException("Acknowledge required."); row.Acknowledged = true; return id; }, ct);
}
public static class SocialRegistration
{
    public static IServiceCollection AddSocialPublishing(this IServiceCollection services) { services.AddScoped<ISocialPublishing, SocialPublishing>(); services.AddSingleton<ISocialEffectLedger, SqlSocialEffectLedger>(); return services; }
